      { x: 0, y: 0, blur: 0, spread: 1, color: "rgba(23, 23, 22, 0.07)" },
    ],
    e2: [
      { x: 0, y: 1, blur: 1, spread: 0, color: "rgba(23, 23, 22, 0.04)" },
      { x: 0, y: 6, blur: 16, spread: -4, color: "rgba(23, 23, 22, 0.1)" },
