      { x: 0, y: 24, blur: 56, spread: -16, color: "rgba(23, 23, 22, 0.3)" },
      { x: 0, y: 0, blur: 0, spread: 1, color: "rgba(23, 23, 22, 0.12)" },
    ],
    top: [{ x: 0, y: 1, blur: 0, spread: 0, color: "rgba(255, 255, 255, 0.9)", inset: true }],
  },
  dark: {
